#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n, t;
    if (!(cin >> n >> t)) return 0;

    // dp[i][y][h][s] = number of sequences of length i (1-indexed),
    // ending with value y (1..4), having h humps so far,
    // and state s = sign of last step (y_i - y_{i-1}):
    // s=0 -> +1, s=1 -> -1.
    // We only need previous layer, so use two 3D arrays.
    long long dp_cur[5][11][2] = {}; // y from 1..4, h from 0..10, s 0/1
    long long dp_nxt[5][11][2] = {};

    // Initialize for i=1: any y in 1..4, h=0, no state yet.
    // We'll handle i=2 separately to set the first step.
    // For i=2, for each pair y1 != y2, h=0, state = sign(y2-y1).
    for (int y1 = 1; y1 <= 4; ++y1) {
        for (int y2 = 1; y2 <= 4; ++y2) {
            if (y1 == y2) continue;
            int s = (y2 > y1) ? 0 : 1;
            dp_cur[y2][0][s] += 1;
        }
    }

    // Iterate i from 3 to n
    for (int i = 3; i <= n; ++i) {
        // Clear next
        for (int y = 1; y <= 4; ++y)
            for (int h = 0; h <= t; ++h)
                dp_nxt[y][h][0] = dp_nxt[y][h][1] = 0;

        for (int prev_y = 1; prev_y <= 4; ++prev_y) {
            for (int h = 0; h <= t; ++h) {
                for (int s = 0; s < 2; ++s) {
                    long long ways = dp_cur[prev_y][h][s];
                    if (ways == 0) continue;
                    for (int y = 1; y <= 4; ++y) {
                        if (y == prev_y) continue;
                        int new_s = (y > prev_y) ? 0 : 1;
                        int new_h = h;
                        // Check if a hump is formed at prev_y (index i-1)
                        // Hump condition: y_{i-2} < y_{i-1} > y_i  -> previous step up (s=0), current step down (new_s=1)
                        if (s == 0 && new_s == 1) {
                            new_h++;
                        }
                        // Valleys are not counted in h, but we don't need to track them separately
                        // because total humps = t and total valleys = t-1 is automatically satisfied
                        // if we only count humps and the sequence starts/ends appropriately?
                        // Actually, we must ensure exactly t humps and exactly t-1 valleys.
                        // However, the problem only asks for sequences with exactly t humps.
                        // But condition says: "there should be precisely t-1 such indexes ... valleys".
                        // So we must enforce both.
                        // We can track valleys similarly, or note that for a sequence with no horizontal segments,
                        // number of humps - number of valleys = (sign of last step) - (sign of first step)? 
                        // Actually, for a sequence y1...yn with no equal adjacent,
                        // let U = number of up steps, D = number of down steps.
                        // Humps = peaks, Valleys = troughs.
                        // It is known that peaks - troughs = (1 if y1 < yn else -1 if y1 > yn else 0) but since no equal adjacent, yn != y1.
                        // More precisely, peaks - troughs = (sign(y_n - y_1) + sign(y_2 - y_1) - sign(y_n - y_{n-1}))/2? Not simple.
                        // Better to track both humps and valleys.
                        // But constraints: n<=20, t<=10, y in 1..4. State space small.
                        // Let's add valley count v.
                    }
                }
            }
        }
        // The above approach needs valley count. Let's redesign state to include valleys.
    }

    // Redesign: dp[i][y][h][v][s]
    // i up to 20, y 4, h up to 10, v up to 10, s 2 -> 20*4*11*11*2 = 19360 states, very small.
    // We'll use two layers for i.
    long long dp2_cur[5][11][11][2] = {};
    long long dp2_nxt[5][11][11][2] = {};

    // Initialize i=2
    for (int y1 = 1; y1 <= 4; ++y1) {
        for (int y2 = 1; y2 <= 4; ++y2) {
            if (y1 == y2) continue;
            int s = (y2 > y1) ? 0 : 1;
            dp2_cur[y2][0][0][s] += 1;
        }
    }

    for (int i = 3; i <= n; ++i) {
        for (int y = 1; y <= 4; ++y)
            for (int h = 0; h <= t; ++h)
                for (int v = 0; v <= t; ++v) // valleys max t
                    dp2_nxt[y][h][v][0] = dp2_nxt[y][h][v][1] = 0;

        for (int prev_y = 1; prev_y <= 4; ++prev_y) {
            for (int h = 0; h <= t; ++h) {
                for (int v = 0; v <= t; ++v) {
                    for (int s = 0; s < 2; ++s) {
                        long long ways = dp2_cur[prev_y][h][v][s];
                        if (ways == 0) continue;
                        for (int y = 1; y <= 4; ++y) {
                            if (y == prev_y) continue;
                            int new_s = (y > prev_y) ? 0 : 1;
                            int new_h = h;
                            int new_v = v;
                            if (s == 0 && new_s == 1) new_h++; // peak
                            if (s == 1 && new_s == 0) new_v++; // valley
                            if (new_h <= t && new_v <= t) {
                                dp2_nxt[y][new_h][new_v][new_s] += ways;
                            }
                        }
                    }
                }
            }
        }
        // swap
        for (int y = 1; y <= 4; ++y)
            for (int h = 0; h <= t; ++h)
                for (int v = 0; v <= t; ++v)
                    for (int s = 0; s < 2; ++s)
                        dp2_cur[y][h][v][s] = dp2_nxt[y][h][v][s];
    }

    long long ans = 0;
    for (int y = 1; y <= 4; ++y) {
        for (int s = 0; s < 2; ++s) {
            ans += dp2_cur[y][t][t-1][s];
        }
    }
    cout << ans << endl;
    return 0;
}
